def render_ruff_config() -> str:
    """Render the blocking Ruff policy for first-party plugin source."""
    return MARKET_ACTIONS_MANAGED_HEADER + '''target-version = "py311"
line-length = 120
extend-exclude = ["vendor"]
respect-gitignore = false

[lint]
select = ["E4", "E7", "E9", "F", "I"]
'''


def _escape(value: str) -> str:
    return (
        value.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\r", "\\r")
        .replace("\n", "\\n")
        .replace("\t", "\\t")
    )


def _market_repo_name(plugin_id: str) -> str:
    return f"{_MARKET_REPO_PREFIX}{plugin_id}"


def _write_support_file(path: Path, content: str, *, created: list[Path], overwrite: bool) -> None:
    if path.exists() and not overwrite:
        return
    path.write_text(content, encoding="utf-8", newline="\n")
    created.append(path)
